.box[hidden] { display: none; }

/* ---------------------------------------------------------------- dial */
.gauge svg { width: 100%; height: 100%; padding: 3%; box-sizing: border-box; font-family: var(--d-font); overflow: visible; }   /* the 3D bezel reaches past the viewBox edge; the padding holds it */
.gauge .face { fill: var(--d-face); }
.gauge .ring { fill: none; stroke: var(--d-ring); stroke-width: 3; }
.gauge .tk { stroke: var(--d-tick); stroke-width: 2.6; }
.gauge .tm { stroke: var(--d-tick); stroke-width: 1.1; opacity: 0.7; stroke-dasharray: 7 99; }   /* 7 of its 12 (gauge.js) */
.gauge .num { fill: var(--d-num); font-size: 15px; font-weight: var(--d-num-weight); font-style: var(--d-value-style); text-anchor: middle; dominant-baseline: central; }
.gauge .lbl { fill: var(--d-label); font-size: 11px; font-weight: 600; text-anchor: middle; letter-spacing: 0.1em; text-transform: uppercase; }
.gauge .note { fill: var(--d-label); font-size: 8.5px; text-anchor: middle; letter-spacing: 0.05em; }
.gauge .val { fill: var(--d-value); font-size: 22px; font-weight: 700; font-style: var(--d-value-style); text-anchor: middle; font-variant-numeric: tabular-nums; }
.gauge .val.end { text-anchor: end; }
.gauge .lcd { display: none; }
/* Vintage: the dial's digital readout in an orange LCD window, like the mph window in a classic VDO tach; recessed in 3D */
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .lcd { display: inline; fill: var(--d-lcd-bg); stroke: #0b0503; stroke-width: 1.4; }
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .val, .dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .gauge .vu { fill: var(--d-lcd); }
.dash[data-theme="vintage3d"] .gauge .lcd { fill: url(#d3-lcd); stroke: url(#d3-lcdedge); stroke-width: 1.6; }
.dash[data-theme="vintage3d"] .gauge .val { filter: url(#d3-glow); }
.gauge .vu { fill: var(--d-label); font-size: 11px; font-weight: 600; text-anchor: start; font-family: var(--d-font); }
