.gauge[data-zone="red"] .val .v { fill: var(--d-red); }
.gauge[data-zone="warn"] .val .v { fill: var(--d-warn); }

/* ---------------------------------------------------------------- big number with its icon */
.big { flex-direction: column; align-items: stretch; justify-content: flex-start; gap: 2cqmin; padding: 4cqmin 4cqmin 6cqmin; font-family: var(--d-font); }   /* name top left, the value, its last minute along the bottom */
.big-v { flex: none; text-align: center; color: var(--d-value); font-size: var(--t-hero); line-height: 0.9; font-weight: 700; font-style: var(--d-value-style); font-variant-numeric: tabular-nums; white-space: nowrap; }
