  .dash[data-theme="vintage3d"] .big.has-dial { grid-template: "dial w1" 1fr "dial w2" 1fr / 100cqh 1fr; padding-right: 4cqmin; padding-block: 4cqmin; }
  .dash[data-theme="vintage3d"] .big.has-dial .big-dial { margin-block: -4cqmin; }
}
@container (max-aspect-ratio: 5/7) {
  .dash[data-theme="vintage3d"] .big.has-dial { grid-template: "dial" 100cqw "w1" 1fr "w2" 1fr / 1fr; padding-inline: 4cqmin; padding-bottom: 4cqmin; }
  .dash[data-theme="vintage3d"] .big.has-dial .big-dial { margin-inline: -4cqmin; }
}
@container (min-aspect-ratio: 7/5) or (max-aspect-ratio: 5/7) {
  .dash[data-theme="vintage3d"] .big.has-dial > .big-win { display: block; grid-area: w1; }
  .dash[data-theme="vintage3d"] .big.has-dial > .big-win2 { grid-area: w2; }
}
/* A dial box's graphs page (gauge.js makeGlance): three numbers over its last 15 minutes, one window */
.glance { padding: 4cqmin; }
.glance-win { position: relative; width: 100%; height: 100%; }
.glance-cv { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
/* In the Vintage styles it is an amber LCD like the dials' readout: a dark orange window with rounded
   corners, recessed, the line in LCD orange with a soft glow and an orange fill under it
   (the canvas reads these, kit.js themeOf). */
.dash:is([data-theme="vintage"], [data-theme="vintage3d"]) .glance-win {
  --d-chart-line: var(--d-lcd); --d-chart-fill: var(--d-lcd); --d-chart-fill-alpha: 0.3; --d-chart-bg: transparent; --d-chart-glow: 6;
  --d-label: rgba(255, 106, 31, 0.75); --d-grid: rgba(255, 106, 31, 0.16); --d-value: #ffd2b0;
  --d-chart-num: #fff1e4; --d-chart-tag-ink: #1a0904;   /* warm white numbers over the chart; dark ink on the orange Now tag */
  background: linear-gradient(#150703, #2a120a 35%, #32170c); border-radius: 3cqmin; border: 1px solid #0b0503; }
.dash[data-theme="vintage3d"] .glance-win { box-shadow: inset 0 1cqmin 2.5cqmin rgba(0, 0, 0, 0.75), 0 1px 0 rgba(255, 255, 255, 0.12); }
.dash[data-theme="vintage3d"] .big-win { border-radius: 2.4cqmin; background: rgba(0, 0, 0, 0.22); }
.dash[data-theme="vintage3d"] .big-win::after { content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
  box-shadow: inset 0 0.8cqmin 2cqmin rgba(0, 0, 0, 0.8), inset 0 -1px 0 rgba(255, 255, 255, 0.07);
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0) 40%); }
.big-k { flex: none; display: flex; align-items: center; gap: 1.5cqmin; color: var(--d-label); font-size: var(--t-lbl); font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; }
.ico { width: 7cqmin; height: 7cqmin; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.big[data-zone="red"] .big-v .v, .grid [data-zone="red"] .v { color: var(--d-red); }
.big[data-zone="warn"] .big-v .v, .grid [data-zone="warn"] .v { color: var(--d-warn); }

/* ---------------------------------------------------------------- Lambda Twin (twin.js) */
.twin { flex-direction: column; align-items: stretch; justify-content: space-between; gap: 2cqmin; padding: 6cqmin 6cqmin 7cqmin; font-family: var(--d-font); }
.tw-head { display: flex; justify-content: space-between; align-items: baseline; color: var(--d-label); font-size: var(--t-lbl); font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; }
.tw-split { color: var(--d-warn); font-weight: 700; }
