.tw-bar::after { content: ""; position: absolute; left: calc(50% - 1px); top: -3cqh; bottom: -3cqh; width: 2px; background: var(--d-value); }
.tw-band { position: absolute; top: 0; bottom: 0; left: var(--tw-band-l); width: var(--tw-band-w); background: color-mix(in srgb, var(--d-ok) 16%, transparent); }
.tw-fill { position: absolute; top: 0; bottom: 0; left: 50%; width: 0; border-radius: 4px; background: var(--d-ok); }
.tw-tick { position: absolute; top: -2cqh; bottom: -2cqh; width: 4px; margin-left: -2px; background: var(--d-value); border-radius: 2px; }
.tw-cut { display: none; position: absolute; inset: 0 0 0 50%; align-items: center; justify-content: center; color: var(--d-label); font-size: var(--t-lbl); font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase;
  background: repeating-linear-gradient(-45deg, transparent 0 5px, var(--d-grid) 5px 8px); border-radius: 0 99px 99px 0; }
