.tw-row[data-st="danger"] .tw-n { color: var(--d-red); } .tw-row[data-st="danger"] .tw-fill { background: var(--d-red); }
.tw-scale { display: grid; grid-template-columns: 36% 1fr 1fr 1fr 1fr; column-gap: 4cqmin; color: var(--d-label); font-size: var(--t-lbl); font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; }
