.speed .sp-row .br { color: var(--d-red); } .speed .sp-row .ac { color: var(--d-ok); }
.speed .sp-bar { position: relative; width: 100%; height: 6cqh; border-radius: 99px; background: var(--d-track); }
.speed .sp-bar::after { content: ""; position: absolute; left: calc(50% - 1px); top: -1cqh; bottom: -1cqh; width: 2px; background: var(--d-value); }
.speed .sp-bar i { position: absolute; top: 0; bottom: 0; left: 50%; width: 0; border-radius: 4px; background: var(--d-ok); }
.speed .sp-bar i[data-dir="brake"] { background: var(--d-red); }
.gmeter canvas { position: absolute; inset: 4cqmin; width: calc(100% - 8cqmin); height: calc(100% - 8cqmin); }
.gmeter .gm-read { position: absolute; left: 5cqmin; bottom: 4cqmin; color: var(--d-value); font: 700 var(--t-value)/1 var(--d-font); font-variant-numeric: tabular-nums; }
