    label(g, T, k, x, y + Z.lbl, Z.lbl);
    const tw = fixed(g, t, x, base, font(T, size), T.fg);
    if (unit) text(g, unit, x + tw + 3, base, font(T, Z.small * 0.7, 600), T.label);
  });
  return top + Math.ceil(4 / cols) * rowH + p * 0.4;
}
function note(g, T, Z, x, y, w, h, s) { text(g, s, x + w / 2, y + h / 2, font(T, Z.small, 600), T.label, 'center'); }

// The readings of the last spanMs as a line, with real breaks marked.
function hourChart(g, T, Z, v, d, now, spanMs, x, y, cw, chh) {
  const rows = d.rows.filter((q) => q.t > now - spanMs);
  const points = rows.map((q) => ({ t: q.t, v: v.conv(q.v) })), { at, ts, breaks } = timeChart(points, now, GAP_MS, HOUR_POINTS);
  const r = niceRange([...at], v.minSpan) || { lo: v.ch.min, hi: v.ch.max, step: (v.ch.max - v.ch.min) / 2 };
  const gapMs = breaks.reduce((t, q) => t + q.ms, 0), held = rows.length ? now - rows[0].t - gapMs : 0;
  trace(g, T, x, y, cw, chh, { span: HOUR_POINTS, lo: r.lo, hi: r.hi, grid: grid(r), gridLabel: gridText(r), breaks, sparse: true,
    timeLabel: rows.length ? `${Math.max(1, Math.round(held / 60_000))} min of data` : '', tip: (k, val) => [clock12(ts[k]), valText(v.ch, val)],
    series: [{ fn: (k) => at[k], color: T.fg, w: 2.5, fill: T.fg, alpha: 0.08 }] });
  if (!rows.length) note(g, T, Z, x, y, cw, chh, d.loaded ? 'No data' : 'Loading');
}

function drawHour(g, w, h, T, key, p, Z) {
  const v = view(key), d = trendData('hour', key), now = Date.now(), rows = d.rows.filter((x) => x.t > now - HOUR_MS);
  const s = summarize(rows.map((x) => x.v)), move = v.span / 4;
  const trend = runTrend(rows.map((x) => [x.t, x.v]), { minMove: move, maxGapMs: GAP_MS, maxMs: TREND_MAX_MS, minMs: 60_000 });
  const y = header(g, T, Z, v, p, w, h, nowText(key, v.ch, rows[rows.length - 1]?.v), s, trend, HOUR_MS, 'h'), cw = w - 2 * p;
  if (h <= w * 1.2) { hourChart(g, T, Z, v, d, now, HOUR_MS, p, y, cw, h - y - p); return; }
  const [a, b] = twoCharts(y, h - p, p * 0.6);   // upright: the hour, then its last 15 minutes up close
  hourChart(g, T, Z, v, d, now, HOUR_MS, p, a.y, cw, a.h);
  hourChart(g, T, Z, v, d, now, TREND_MAX_MS, p, b.y, cw, b.h);
}

// The last `days` days as bars from each day's min to its max, a tick at its average.
function dayChart(g, T, Z, v, d, days, x0, y, cw, chh) {
  const today = Date.parse(`${d.today || new Date().toISOString().slice(0, 10)}T00:00:00Z`), byDay = new Array(days).fill(null);
  for (const x of d.rows) {
    const k = Math.round((today - Date.parse(`${x.day}T00:00:00Z`)) / DAY_MS);
    if (k >= 0 && k < days) byDay[k] = x;
  }
  const held = byDay.filter(Boolean), vals = held.flatMap((x) => [v.conv(x.min), v.conv(x.max)]);
  const r = niceRange(vals, v.minSpan) || { lo: v.ch.min, hi: v.ch.max, step: (v.ch.max - v.ch.min) / 2 };
  const { slots, breaks } = collapseGaps(byDay.map(Boolean), DAY_MS), n = slots.length, span = n + 1;   // each day owns a slot; missing days are one small mark
  trace(g, T, x0, y, cw, chh, { span: Math.max(2, span), lo: r.lo, hi: r.hi, grid: grid(r), gridLabel: gridText(r), breaks,
    timeLabel: held.length ? `${held.length} day${held.length === 1 ? '' : 's'} of data` : '',
    series: [] });
  const { P } = axes(x0, y, cw, chh, Math.max(2, span), r.lo, r.hi, breaks), bar = n ? Math.max(3, Math.min(48, ((cw - breaks.length * GAP_PX) / n) * 0.6)) : 0;
  const tips = [];
  slots.forEach((k, q) => {
    const x = byDay[k];
    tips.push([P(q + 0.5, 0)[0], [dayText(x.day), `Max ${valText(v.ch, v.conv(x.max))}`, `Avg ${valText(v.ch, v.conv(x.avg))}`, `Min ${valText(v.ch, v.conv(x.min))}`]]);
    const c0 = q + 0.5, [a, b] = P(c0, v.conv(x.min)), [c, e] = P(c0, v.conv(x.max)), [m, o] = P(c0, v.conv(x.avg));
    g.save(); g.globalAlpha = 0.4; line(g, a, b, c, e, T.fg, bar); g.restore();
    line(g, m - bar / 2, o, m + bar / 2, o, T.fg, 3);
  });
  addTip(g.canvas, { x: x0, y, w: cw, h: chh }, (mx) => nearest(tips, mx));
  if (!held.length) note(g, T, Z, x0, y, cw, chh, d.loaded ? 'No data' : 'Loading');
}
// "Tue Nov 24" for a day's "2026-11-24" (the day as stored, not moved by the time zone).
const dayText = (day) => new Date(`${day}T12:00:00Z`).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC' }).replace(',', '');

function drawDays(g, w, h, T, key, p, Z) {
  const v = view(key), d = trendData('days', key), s = summarizeDays(d.rows);
  const trend = runTrend(d.rows.map((x) => [Date.parse(`${x.day}T00:00:00Z`), x.avg]), { minMove: v.span / 4, minPoints: 2, minMs: DAY_MS });
  const y = header(g, T, Z, v, p, w, h, nowText(key, v.ch, null), s, trend, DAY_MS, 'd'), cw = w - 2 * p;
  if (h <= w * 1.2) { dayChart(g, T, Z, v, d, DAYS, p, y, cw, h - y - p); return; }
  const [a, b] = twoCharts(y, h - p, p * 0.6);   // upright: 30 days, then the last 7 up close
  dayChart(g, T, Z, v, d, DAYS, p, a.y, cw, a.h);
  dayChart(g, T, Z, v, d, 7, p, b.y, cw, b.h);
}

// Full screen level 1 (the last hour) or 2 (the last 30 days).
export function drawHistory(g, w, h, level, T, key) {
  const p = Math.round(Math.min(w, h) * 0.05) + 6, Z = typeScale(w, h);
  (level === 1 ? drawHour : drawDays)(g, w, h, T, key, p, Z);
}

files.kit/twin.js:
// kit/twin.js: the app's kit/twin.js as forked with tunerloop-dash. Yours to change.
// The Lambda Twin box: both banks on one scale centred on the target, so the driver reads the error,
// not two numbers. Bars grow left for rich and right for lean (+-15 % full scale), with the +-3 %
// target band shaded. A SPLIT note appears when the banks differ by more than 0.04. On overrun
// (throttle shut above 1500 rpm, where the injectors cut and the widebands read air) it says CUT
// instead of showing a scary lean number. Numbers are in the chosen mixture unit (units.js).
import { CHANNELS, shown, reading } from './channels.js';
import { steadyText } from './steady.js';

const RANGE = 0.15, BAND = 0.03, SPLIT = 0.04;
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

// Fuel cut on overrun: throttle closed with the revs up. (A Link fuel-cut channel would be better
// when the live block carries one.)
export const overrun = (r) => (r?.tps_pct ?? 100) < 2 && (r?.rpm ?? 0) > 1500;

// 'ok' | 'rich' | 'lean' | 'danger' | 'cut' | '' for one bank: e is the error (0.05 = 5 % lean).
export function bankState(e, cut) {
  if (cut) return 'cut';
  if (e === null) return '';
  return e > 0.08 ? 'danger' : e > BAND ? 'lean' : e < -BAND ? 'rich' : 'ok';
}

// Where a bank's bar sits, in % of the track width: { left, width, tick }.
export function barGeom(e) {
  const x = Math.max(-RANGE, Math.min(RANGE, e)) / RANGE * 50;
  return { left: 50 + Math.min(0, x), width: Math.abs(x), tick: 50 + x };
}

export function makeTwin() {
  const banks = [['lambda1', 'Bank 1'], ['lambda2', 'Bank 2']].map(([key, name]) => {
    const ch = shown(CHANNELS[key]);
    return { key, name: ch.note ? `${name} \u00b7 ${ch.note}` : name, ch, text: steadyText(ch) };   // its note (the dash's ranges): which cylinders it reads
  });
  const tgt = shown(CHANNELS.lambda_target);
  const el = document.createElement('div');
  el.className = 'box twin';
  el.innerHTML = `<div class="tw-head"><span>${esc(banks[0].ch.label.replace(/ 1$/, ''))}</span><span class="tw-split" hidden></span><span class="tw-tgt"></span></div>
    ${banks.map((b) => `<div class="tw-row"><div class="tw-k">${esc(b.name)}</div><div class="tw-n">-</div>
      <div class="tw-bar"><i class="tw-band"></i><i class="tw-fill"></i><i class="tw-tick"></i><span class="tw-cut">Fuel cut</span></div></div>`).join('')}
    <div class="tw-scale"><span class="rich">Rich</span><span>&minus;5%</span><span>+5%</span><span class="lean">Lean</span></div>`;
  const rows = [...el.querySelectorAll('.tw-row')].map((row) => ({ row, n: row.querySelector('.tw-n'), fill: row.querySelector('.tw-fill'), tick: row.querySelector('.tw-tick') }));
  const tgtEl = el.querySelector('.tw-tgt'), splitEl = el.querySelector('.tw-split');
  el.style.setProperty('--tw-band-l', `${50 - BAND / RANGE * 50}%`);
  el.style.setProperty('--tw-band-w', `${BAND / RANGE * 100}%`);
  return {
    el,
    // r: the whole reading (base units), since the box needs both banks, the target and the throttle.
    set(r) {
      const t = reading(CHANNELS.lambda_target, r?.lambda_target);
      const target = t ?? 1;
      tgtEl.textContent = t === null ? 'Target -' : `Target ${tgt.text(t)}`;
      const cut = overrun(r);
      const vals = banks.map((b) => reading(CHANNELS[b.key], r?.[b.key]));
      banks.forEach((b, i) => {
        const v = vals[i], e = v === null ? null : v / target - 1, st = bankState(e, cut), g = rows[i];
        g.row.dataset.st = st;
        g.n.textContent = cut ? 'CUT' : b.text(v);
        if (e === null || cut) { g.fill.style.width = '0'; g.tick.hidden = true; return; }
        const { left, width, tick } = barGeom(e);
        g.fill.style.left = `${left}%`; g.fill.style.width = `${width}%`;
        g.tick.hidden = false; g.tick.style.left = `${tick}%`;
      });
      const split = !cut && vals[0] !== null && vals[1] !== null && Math.abs(vals[0] - vals[1]) > SPLIT + 1e-9;
      splitEl.hidden = !split;
      if (split) splitEl.textContent = `Split ${Math.abs(vals[0] - vals[1]).toFixed(2)}`;
    },
    frame() {},
  };
}

files.kit/units.js:
// kit/units.js: the app's kit/units.js as forked with tunerloop-dash. Yours to change.
// Display units: the choices for each kind of reading, the conversion from the base unit the car
// sends (kPa, deg C, km/h, lambda), and the dial range in the chosen unit. Values, zones and valid
// ranges stay in base units everywhere else; only what is shown is converted. The choice is per
// device (localStorage), and a change tells the listeners so open gauges rebuild.
import { store } from './store.js';

export const STOICH = 14.7;          // petrol: AFR = lambda x 14.7

const same = (v) => v;
// kind: { name (the Settings row), def (the default option), options: { key: { name (the
// select's text), unit (after the number), dp (decimals), from (base unit to this one), word
// (optional: replaces "Lambda" in a channel's name, so "Lambda 1" shows as "AFR 1") } } }.
// The first option of each kind is its base unit.
export const UNITS = {
  pressure: { name: 'Pressure', def: 'psi', options: {
    kpa: { name: 'kPa', unit: 'kPa', dp: 0, from: same },
    bar: { name: 'bar', unit: 'bar', dp: 2, from: (v) => v / 100 },
    psi: { name: 'psi', unit: 'psi', dp: 0, from: (v) => v * 0.1450377 },
  } },
  temperature: { name: 'Temperature', def: 'f', options: {
    c: { name: '°C', unit: '°C', dp: 0, from: same },
    f: { name: '°F', unit: '°F', dp: 0, from: (v) => v * 9 / 5 + 32 },
  } },
  speed: { name: 'Speed', def: 'mph', options: {
    kmh: { name: 'km/h', unit: 'km/h', dp: 0, from: same },
    mph: { name: 'mph', unit: 'mph', dp: 0, from: (v) => v / 1.609344 },
  } },
  mixture: { name: 'Mixture', def: 'lambda', options: {
    lambda: { name: 'Lambda', unit: '', dp: 2, from: same },
    afr: { name: 'AFR', unit: 'AFR', dp: 1, from: (v) => v * STOICH, word: 'AFR' },
  } },
};

const KEY = 'ecuai-units';
const listeners = new Set();
let saved = null;                    // { kind: option key } as stored, read once

// The chosen option key for every kind, defaults filled in and unknown keys dropped.
export function units(raw) {
  if (raw === undefined) {
    if (saved === null) { try { saved = JSON.parse(store.get(KEY)) || {}; } catch { saved = {}; } }
    raw = saved;
  }
  return Object.fromEntries(Object.entries(UNITS).map(([kind, u]) => [kind, u.options[raw?.[kind]] ? raw[kind] : u.def]));
}

// In a dash's frame (no storage of its own): the choices the app sends.
export function useUnits(raw) { saved = { ...(raw || {}) }; }

export function setUnit(kind, key) {
  if (!UNITS[kind]?.options[key]) return;
  saved = { ...units(), [kind]: key };
  store.set(KEY, JSON.stringify(saved));
  for (const fn of listeners) fn(units());
}

// fn(choices) on every change; returns a function that stops it.
export function onUnitsChange(fn) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

// The option shown for a kind: { key, name, unit, dp, from, base }. choices: units() by default.
export function unitFor(kind, choices = units()) {
  const u = UNITS[kind];
  const key = u.options[choices[kind]] ? choices[kind] : u.def;
  return { key, ...u.options[key], base: key === Object.keys(u.options)[0] };
}

// A base-unit value in the chosen unit, and as text with that unit's decimals.
export const convert = (kind, v, choices) => unitFor(kind, choices).from(v);
export const format = (kind, v, choices) => { const u = unitFor(kind, choices); return u.from(v).toFixed(u.dp); };

// A round dial step near x: 1, 2 or 5 times a power of ten, the nearest on a log scale.
export function niceStep(x) {
  const p = 10 ** Math.floor(Math.log10(x));
  const f = x / p;
  return +((f < Math.SQRT2 ? 1 : f < Math.sqrt(10) ? 2 : f < Math.sqrt(50) ? 5 : 10) * p).toPrecision(6);
}

// A dial from min to max (display units): about six round steps, the ends on a step.
export function dialRange(min, max) {
  const step = niceStep((max - min) / 6);
  const at = (v) => +(Math.round(v / step) * step).toPrecision(6);
  return { min: at(min), max: at(max), step };
}

